//! Turn validated JSON placements into a normal, opt-in Glue 5 Luau mod.
//!
//! This uses the same streaming/object/entity natives already used by Glue
//! Trainer. It does not load YMAP/RPF or custom YFT/YTD assets: models must
//! already exist in the game's loaded asset catalog.

use crate::pc_mods::{self, PlacementReport};

/// Compile a validated placement list to a conservative, sequential Luau
/// worker. It creates at most one object at a time and yields every four.
pub fn compile(report: &PlacementReport) -> String {
    let mut out = String::from(
        "-- Generated by GLUE 5 PC Mod Importer. Models must already be installed.\n\n         local placements = {\n",
    );
    for p in &report.placements {
        use std::fmt::Write as _;
        let _ = writeln!(
            out,
            "    {{ model = \"{}\", x = {:.6}, y = {:.6}, z = {:.6}, heading = {:.6} }},",
            p.model, p.x, p.y, p.z, p.heading
        );
    }
    out.push_str(
        r#"}
local created = 0
local failed = 0
for index, placement in placements do
    local model = joaat(placement.model)
    if streaming.load(model) then
        local position = vector.create(placement.x, placement.y, placement.z)
        local objectHandle = object.createObject(model, position, false, false, false)
        streaming.setModelAsNoLongerNeeded(model)
        if objectHandle then
            entity.setEntityHeading(objectHandle, placement.heading)
            created += 1
        else
            failed += 1
        end
    else
        failed += 1
    end
    if index % 4 == 0 then
        task.wait(0)
    end
end
print(`PC map finished: {created} objects created, {failed} failed`)
"#,
    );
    out
}

/// Import a supported JSON placement file as an ordinary, disabled-by-default
/// script mod. It becomes visible to refresh()/the Mods page; it is not run
/// until the player enables or starts it.
pub fn install(name: &str, bytes: &[u8]) -> Result<usize, String> {
    if name.is_empty()
        || name.len() > 40
        || !name.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_' || b == b'-')
    {
        return Err("Map name must use lowercase letters, digits, - or _ (max 40)".into());
    }
    let report = pc_mods::parse_placements(bytes)?;
    if report.placements.is_empty() {
        return Err("placement JSON contains no objects".into());
    }
    let dir = crate::dir().ok_or("mods are off")?;
    let target = dir.join(name);
    if target.exists() {
        return Err(format!("Mod {name} already exists"));
    }

    let mut random = [0u8; 6];
    getrandom::fill(&mut random).map_err(|e| format!("staging name: {e}"))?;
    let suffix = random.iter().map(|b| format!("{b:02x}")).collect::<String>();
    let staging = dir.join(format!(".stage-map-{name}-{suffix}"));
    std::fs::create_dir(&staging).map_err(|e| format!("create map staging directory: {e}"))?;

    let result = (|| {
        std::fs::write(staging.join("main.luau"), compile(&report))
            .map_err(|e| format!("write map script: {e}"))?;
        std::fs::write(staging.join("mod.json"), "{\n  \"autostart\": false\n}\n")
            .map_err(|e| format!("write map settings: {e}"))?;
        std::fs::rename(&staging, &target).map_err(|e| format!("install map mod: {e}"))?;
        Ok(())
    })();
    if result.is_err() {
        let _ = std::fs::remove_dir_all(&staging);
    } else {
        crate::changed(&format!("{name}/"));
        crate::refresh();
    }
    result.map(|()| report.placements.len())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_script_uses_existing_game_natives_and_yields() {
        let report = pc_mods::parse_placements(
            br#"{"objects":[{"model":"prop_roadcone02b","x":1,"y":2,"z":3,"heading":90}]}"#,
        )
        .unwrap();
        let script = compile(&report);
        assert!(script.contains("local model = joaat(placement.model)"));
        assert!(script.contains("streaming.load(model)"));
        assert!(script.contains("object.createObject(model, position, false, false, false)"));
        assert!(script.contains("entity.setEntityHeading(objectHandle, placement.heading)"));
        assert!(script.contains("task.wait(0)"));
        assert!(script.contains("prop_roadcone02b"));
    }
}
